    public static Waveform find(Waveform[] table, String id, int simpleFreq) {
        if (id == null || SIMPLE_ID.equals(id)) return Waveform.simple(simpleFreq);
        for (Waveform w : table) if (w.id.equals(id)) return w;
        return Waveform.simple(simpleFreq);
    }

    public static int indexOf(Waveform[] table, String id) {
        for (int i = 0; i < table.length; i++) if (table[i].id.equals(id)) return i + 1;   // 0 = simple
        return 0;
    }
